import { NotImplementedError } from "./util/NotImplementedError.js";
import { path } from "./util/node.js";
/**
 * @public
 */
export class WzObject {
    constructor() {
        // public hcTag: any = null
        // public hcTag_spine: any = null
        // public msTag: any = null
        // public msTag_spine: any = null
        // public tag3: any = null
        this._disposed = false;
        // public abstract remove (): void
    }
    /**
     * @virtual
     */
    get wzValue() {
        return null;
    }
    /**
     * @virtual
     */
    getBitmap() {
        throw new NotImplementedError('[WzObject#getBitmap]');
    }
    getTopMostWzDirectory() {
        let parent = this.parent;
        if (parent == null) {
            return this;
        }
        while (parent.parent != null) {
            parent = parent.parent;
        }
        return parent;
    }
    get fullPath() {
        let result = this.name;
        let currObj = this;
        while (currObj.parent != null) {
            currObj = currObj.parent;
            result = currObj.name + path.sep + result;
        }
        return result;
    }
}
